@@
 func handleRoute(w http.ResponseWriter, r *http.Request) {
+	rules, err := parseRouteConfig(r.Header.Get("X-Route-Config"))
+	if err != nil {
+		log.Fatal("malformed route configuration: ", err)
+	}
+	destination := selectRoute(readLabels(r), rules)
+	io.WriteString(w, destination)
 }

@@
+func TestSelectRouteExactMatch(t *testing.T) {
+	rules := []Rule{{Label: "env", Value: "prod", Destination: "primary"}}
+	if got := selectRoute(map[string]string{"env": "prod"}, rules); got != "primary" { t.Fatalf("got %q", got) }
+}
+
+func TestSelectRouteNoMatch(t *testing.T) {
+	rules := []Rule{{Label: "env", Value: "prod", Destination: "primary"}}
+	if got := selectRoute(map[string]string{"env": "dev"}, rules); got != defaultDestination { t.Fatalf("got %q", got) }
+}
+
+func TestSelectRouteFirstMatch(t *testing.T) {
+	rules := []Rule{{Label: "env", Value: "prod", Destination: "primary"}, {Label: "region", Value: "west", Destination: "west"}}
+	if got := selectRoute(map[string]string{"env": "prod", "region": "west"}, rules); got != "primary" { t.Fatalf("got %q", got) }
+}
